// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// A brick sitting at a known position, with the same shape as the grid bricks.
function brickAt(x, y) {
  return { x, y, w: BRICK_W, h: BRICK_H, alive: true, points: 10, row: 0 };
}

// === Brick bounce (the reported symptom: the ball plows straight through) ===

test('brick: rising into the bottom face bounces back down and is pushed out', () => {
  const state = createState(1);
  const brick = brickAt(100, 100);
  state.bricks = [brick];
  state.ball = { x: 136, y: 125, r: BALL_R, vx: 0, vy: -300 };
  step(state, 1 / 60); // ball rises into the brick's bottom face
  const broken = resolveBrickCollisions(state);
  assert.equal(broken, 1);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy > 0, 'vy flipped from up to down');
  assert.equal(state.ball.y, brick.y + brick.h + BALL_R, 'ball pushed out below the brick');
  assert.equal(collides(state.ball, brick), false, 'ball no longer overlaps the brick');
  // One bounce per pass: a second resolve must not re-flip or double-score.
  const scoreBefore = state.score;
  assert.equal(resolveBrickCollisions(state), 0);
  assert.ok(state.ball.vy > 0, 'no re-inversion');
  assert.equal(state.score, scoreBefore, 'brick counted exactly once');
});

test('brick: a side hit flips only vx and pushes the ball out sideways', () => {
  const state = createState(1);
  const brick = brickAt(100, 100);
  state.bricks = [brick];
  state.ball = { x: 93, y: 110, r: BALL_R, vx: 300, vy: 0 };
  step(state, 1 / 60); // ball drives into the brick's left face
  resolveBrickCollisions(state);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vx < 0, 'vx flipped from right to left');
  assert.equal(state.ball.x, brick.x - BALL_R, 'ball pushed out on the left side');
  assert.equal(state.ball.vy, 0, 'vertical component untouched');
  assert.equal(collides(state.ball, brick), false);
});

test('brick: equal penetrations at a corner flip both components', () => {
  const state = createState(1);
  const brick = brickAt(100, 100);
  state.bricks = [brick];
  // Ball center exactly on the brick's top-left corner: 7 px penetration on
  // both axes -> a corner, so BOTH components invert.
  state.ball = { x: brick.x, y: brick.y, r: BALL_R, vx: 300, vy: 300 };
  const broken = resolveBrickCollisions(state);
  assert.equal(broken, 1);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'both components flip');
  assert.equal(state.ball.x, brick.x - BALL_R);
  assert.equal(state.ball.y, brick.y - BALL_R);
});

test('brick: a seam between two bricks flips the axis exactly once and breaks both', () => {
  const state = createState(1);
  const a = brickAt(100, 100);
  const b = brickAt(100 + BRICK_W + BRICK_GAP, 100);
  state.bricks = [a, b];
  state.ball = { x: 176, y: 93, r: BALL_R, vx: 0, vy: 300 };
  step(state, 1 / 60); // falls into the seam between the two bricks
  const broken = resolveBrickCollisions(state);
  assert.equal(broken, 2, 'both bricks broken');
  assert.equal(a.alive, false);
  assert.equal(b.alive, false);
  assert.ok(state.ball.vy < 0, 'exactly one flip: the ball bounces back up');
  assert.equal(state.ball.y, a.y - BALL_R, 'pushed out above the row');
  assert.equal(collides(state.ball, a), false);
  assert.equal(collides(state.ball, b), false);
});

