test('brick: a level-6 max step (35 px > 34 px brick) cannot tunnel through', () => {
  const state = createState(6);
  const brick = brickAt(100, 100);
  state.bricks = [brick];
  const speed = ballSpeed(6);
  // Bottom edge at 99, just above the brick; one max frame step (0.05 s) moves
  // the ball 35.5 px — past the whole 34 px obstacle (BRICK_H + 2*BALL_R).
  state.ball = { x: 136, y: 92, r: BALL_R, vx: 0, vy: speed };
  step(state, 0.05);
  const broken = resolveBrickCollisions(state);
  assert.equal(broken, 1);
  assert.equal(brick.alive, false);
  assert.ok(state.ball.vy < 0, 'bounced, not tunneled');
  assert.ok(state.ball.y < brick.y, 'ball stays above the brick');
});

test('brick: same outcome at dt=0.05 and at two dt=0.025 steps (dt independence)', () => {
  const run = (dts) => {
    const state = createState(6);
    const brick = brickAt(100, 100);
    state.bricks = [brick];
    state.ball = { x: 136, y: 92, r: BALL_R, vx: 0, vy: ballSpeed(6) };
    for (const dt of dts) {
      step(state, dt);
      resolveBrickCollisions(state);
    }
    return { brick, ball: state.ball };
  };
  const coarse = run([0.05]);
  const fine = run([0.025, 0.025]);
  assert.equal(coarse.brick.alive, false);
  assert.equal(fine.brick.alive, false);
  assert.ok(coarse.ball.vy < 0 && fine.ball.vy < 0, 'both configurations bounce');
});

test('brick: a head-on hit with vx=0 keeps a playable trajectory (dead spot)', () => {
  const state = createState(1);
  const brick = brickAt(100, 100);
  state.bricks = [brick];
  state.ball = { x: 136, y: 118, r: BALL_R, vx: 0, vy: -300 };
  resolveBrickCollisions(state);
  assert.ok(
    Math.abs(state.ball.vx) >= MIN_VX_FRACTION * ballSpeed(1),
    '|vx| above the dead spot'
  );
});

