// Paddle — swept: the ball bounces iff its bottom edge crossed the paddle's
// top plane during this step (or the ball is inside the paddle, e.g. after
// the mouse teleported the paddle onto it). A fast ball therefore always
// exits through the top of the paddle instead of tunnelling through its
// 12 px height.
const prevBottom = ball.py + ball.r;
const newBottom = ball.y + ball.r;
const overPaddle = ball.x >= paddle.x && ball.x <= paddle.x + paddle.w;
const crossedTop =
  ball.vy > 0 && prevBottom <= paddle.y && newBottom >= paddle.y;
const insidePaddle =
  ball.vy > 0 && newBottom >= paddle.y && ball.y - ball.r <= paddle.y + paddle.h;
if (overPaddle && (crossedTop || insidePaddle)) {
  // Place the ball where its bottom edge meets the paddle's top plane.
  if (crossedTop) {
    const t = (paddle.y - prevBottom) / (newBottom - prevBottom);
    ball.x = ball.px + (ball.x - ball.px) * t;
  }
  ball.y = paddle.y - ball.r;
  ball.vy = -Math.abs(ball.vy);
  // The rebound angle depends on where the paddle was hit.
  const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
  ball.vx = ballSpeed(state.level) * 0.6 * hit;
  state.combo = 0; // touching the paddle resets the combo
}

