test('paddle: the rebound preserves the level speed (norm)', () => {
  const state = createState(1);
  const speed = ballSpeed(1);
  // Hit at the very edge of the paddle (hit = 1): vx = 0.6 * speed, and the
  // norm must still be exactly the level speed.
